}
","import React, { useEffect, useState } from "react";

interface MetricData {
 label: string;
 value: number | null;
 color: string;
 loading: boolean;
}

const API_HEADERS = {
 Accept: "application/json",
 "Content-Type": "application/json",
 "X-UserToken": (window as any).g_ck || ""
};

async function fetchCount(table: string, query: string): Promise<number> {
 const params = new URLSearchParams({
 sysparm_query: query,
 sysparm_fields: "sys_id",
 sysparm_limit: "1",
 sysparm_suppress_pagination_header: "false"
 });
 const response = await fetch(`/api/now/table/${table}?${params}`, {
 headers: API_HEADERS
 });
 const totalHeader = response.headers.get("X-Total-Count");
 if (totalHeader) {
 return parseInt(totalHeader, 10);
 }
 const data = await response.json();
 return data.result ? data.result.length : 0;
}

export default function OperationalSnapshot() {
 const [metrics, setMetrics] = useState<MetricData[]>([
 { label: "Critical Stores", value: null, color: "#ef4444", loading: true },
 { label: "Open Complaints", value: null, color: "#f59e0b", loading: true },
 { label: "Today's Refunds", value: null, color: "#3b82f6", loading: true },
 { label: "Fraud Alerts", value: null, color: "#06b6d4", loading: true }
 ]);

 useEffect(() => {
 const loadMetrics = async () => {
 const queries = [
 { table: "x_2145749_qc_dark_store", query: "x_2145749_qc_statusINcritical,offline" },
 { table: "sn_customerservice_case", query: "active=true" },
 { table: "x_2145749_qc_refund_request", query: "sys_created_onONToday@javascript:gs.beginningOfToday()@javascript:gs.endOfToday()" },
 { table: "x_2145749_qc_fraud_flag", query: "active=true" }
 ];

 const results = await Promise.allSettled(
 queries.map((q) => fetchCount(q.table, q.query))
 );

 setMetrics((prev) =>
 prev.map((metric, i) => {
 const result = results[i];
 return {
 ...metric,
 value: result.status === "fulfilled" ? result.value : 0,
 loading: false
 };
 })
 );
 };

 loadMetrics();
 }, []);

 return (
 <section className="operational-snapshot">
 <h2 className="section-title">Operational Snapshot</h2>
 <div className="metrics-grid">
 {metrics.map((metric) => (
 <div key={metric.label} className="metric-card">
 <div className="metric-indicator">
 <span
 className="metric-dot"
 style={{ backgroundColor: metric.color }}
 />
 <span className="metric-label">{metric.label}</span>
 </div>
 <div className="metric-value">
 {metric.loading ? (
 <span className="metric-loading">...</span>
 ) : (
 <span className="metric-number">{metric.value}</span>
 )}
 </div>
 </div>
 ))}
 </div>
 </section>
 );
}
",":root {
 --do-bg-primary: #0b0f19;
 --do-bg-secondary: #131825;
 --do-bg-card: #161b2e;
 --do-bg-card-hover: #1c2340;
 --do-border-card: rgba(139, 92, 246, 0.15);
 --do-border-card-hover: rgba(139, 92, 246, 0.4);
 --do-text-primary: #ffffff;
 --do-text-secondary: #94a3b8;
 --do-text-muted: #64748b;
 --do-accent-purple: #a855f7;
 --do-accent-indigo: #6366f1;
 --do-accent-violet: #8b5cf6;
 --do-glow-purple: rgba(168, 85, 247, 0.3);
 --do-glow-purple-strong: rgba(168, 85, 247, 0.5);
 --do-gradient-cta: linear-gradient(135deg, #a855f7, #6366f1);
 --do-gradient-cta-hover: linear-gradient(135deg, #c084fc, #818cf8);
 --do-shadow-card: 0 4px 24px rgba(0, 0, 0, 0.3);
 --do-shadow-card-hover: 0 8px 40px rgba(139, 92, 246, 0.25);
 --do-shadow-glow: 0 0 30px rgba(168, 85, 247, 0.4);
 --do-radius-card: 16px;
 --do-radius-pill: 50px;
 --do-transition-smooth: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
 --do-font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

* {
 margin: 0;
 padding: 0;
 box-sizing: border-box;
}

body {
 background-color: var(--do-bg-primary);
 color: var(--do-text-primary);
 font-family: var(--do-font-family);
 line-height: 1.6;
 min-height: 100vh;
 -webkit-font-smoothing: antialiased;
 -moz-osx-font-smoothing: grayscale;
}

.darkops-app {
 min-height: 100vh;
 display: flex;
 flex-direction: column;
}

/* ===== HEADER ===== */
.darkops-header {
 text-align: center;
 padding: 60px 24px 40px;
 background: radial-gradient(ellipse at top center, rgba(139, 92, 246, 0.08) 0%, transparent 60%);
}

.header-brand {
 margin-bottom: 24px;
}

.header-logo {
 display: inline-flex;
 align-items: center;
 justify-content: center;
 margin-bottom: 16px;
 filter: drop-shadow(0 0 20px var(--do-glow-purple));
 animation: pulse-glow 3s ease-in-out infinite;
}

@keyframes pulse-glow {
 0%, 100% { filter: drop-shadow(0 0 20px var(--do-glow-purple)); }
 50% { filter: drop-shadow(0 0 35px var(--do-glow-purple-strong)); }
}

.header-title {
 font-size: 3rem;
 font-weight: 800;
 letter-spacing: -0.02em;
 background: var(--do-gradient-cta);
 -webkit-background-clip: text;
 -webkit-text-fill-color: transparent;
 background-clip: text;
 margin-bottom: 8px;
}

.header-subtitle {
 font-size: 1.25rem;
 color: var(--do-text-secondary);
 font-weight: 400;
 margin-bottom: 8px;
}

.header-microcopy {
 font-size: 0.875rem;
 color: var(--do-text-muted);
}

.header-greeting {
 margin: 24px 0;
 font-size: 1.1rem;
 color: var(--do-text-secondary);
}

.highlight-user {
 color: var(--do-accent-purple);
 font-weight: 600;
}

/* ===== CTA BUTTON ===== */
.header-cta {
 margin-top: 24px;
}

.cta-button {
 display: inline-flex;
 align-items: center;
 gap: 16px;
 background: var(--do-gradient-cta);
 color: var(--do-text-primary);
 border: none;
 border-radius: var(--do-radius-pill);
 padding: 16px 32px;
 font-size: 1rem;
 font-family: var(--do-font-family);
 cursor: pointer;
 transition: var(--do-transition-smooth);
 box-shadow: 0 4px 20px var(--do-glow-purple);
 position: relative;
 overflow: hidden;
}

.cta-button::before {
 content: "";
 position: absolute;
 inset: 0;
 background: var(--do-gradient-cta-hover);
 opacity: 0;
 transition: opacity 0.3s ease;
}

.cta-button:hover {
 transform: translateY(-2px) scale(1.02);
 box-shadow: var(--do-shadow-glow);
}

.cta-button:hover::before {
 opacity: 1;
}

.cta-button:active {
 transform: translateY(0) scale(0.98);
}

.cta-icon {
 font-size: 1.3rem;
 position: relative;
 z-index: 1;
}

.cta-content {
 display: flex;
 flex-direction: column;
 text-align: left;
 position: relative;
 z-index: 1;
}

.cta-label {
 font-weight: 600;
 font-size: 1rem;
}

.cta-desc {
 font-size: 0.75rem;
 opacity: 0.8;
}

.cta-arrow {
 font-size: 1.4rem;
 position: relative;
 z-index: 1;
 transition: transform 0.3s ease;
}

.cta-button:hover .cta-arrow {
 transform: translateX(4px);
}

/* ===== MAIN CONTENT ===== */
.darkops-main {
 flex: 1;
 padding: 0 24px 60px;
 max-width: 1200px;
 margin: 0 auto;
 width: 100%;
}

.section-title {
 font-size: 1.5rem;
 font-weight: 700;
 color: var(--do-text-primary);
 margin-bottom: 24px;
 padding-left: 4px;
}

/* ===== COMMAND CENTERS GRID ===== */
.command-centers {
 margin-bottom: 60px;
}

.cards-grid {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
 gap: 24px;
}

.command-card {
 background: var(--do-bg-card);
 border: 1px solid var(--do-border-card);
 border-radius: var(--do-radius-card);
 padding: 28px;
 transition: var(--do-transition-smooth);
 cursor: pointer;
 position: relative;
 overflow: hidden;
}

.command-card::before {
 content: "";
 position: absolute;
 top: 0;
 left: 0;
 right: 0;
 height: 3px;
 background: var(--do-gradient-cta);
 opacity: 0;
 transition: opacity 0.3s ease;
}

.command-card:hover {
 transform: translateY(-6px);
 border-color: var(--do-border-card-hover);
 box-shadow: var(--do-shadow-card-hover);
 background: var(--do-bg-card-hover);
}

.command-card:hover::before {
 opacity: 1;
}

.card-icon {
 font-size: 2rem;
 margin-bottom: 16px;
}

.card-title {
 font-size: 1.125rem;
 font-weight: 600;
 color: var(--do-text-primary);
 margin-bottom: 10px;
}

.card-description {
 font-size: 0.875rem;
 color: var(--do-text-secondary);
 line-height: 1.5;
 margin-bottom: 20px;
}

.card-launch {
 display: inline-flex;
 align-items: center;
 gap: 6px;
 background: none;
 border: none;
 color: var(--do-accent-purple);
 font-size: 0.875rem;
 font-weight: 600;
 font-family: var(--do-font-family);
 cursor: pointer;
 padding: 0;
 transition: var(--do-transition-smooth);
}

.card-launch:hover {
 color: var(--do-accent-violet);
}

.launch-arrow {
 transition: transform 0.3s ease;
}

.command-card:hover .launch-arrow {
 transform: translateX(4px);
}

/* ===== OPERATIONAL SNAPSHOT ===== */
.operational-snapshot {
 margin-bottom: 40px;
}

.metrics-grid {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
 gap: 20px;
}

.metric-card {
 background: var(--do-bg-card);
 border: 1px solid var(--do-border-card);
 border-radius: var(--do-radius-card);
 padding: 24px;
 display: flex;
 flex-direction: column;
 gap: 16px;
 transition: var(--do-transition-smooth);
}

.metric-card:hover {
 transform: translateY(-3px);
 border-color: var(--do-border-card-hover);
 box-shadow: var(--do-shadow-card-hover);
}

.metric-indicator {
 display: flex;
 align-items: center;
 gap: 10px;
}

.metric-dot {
 width: 10px;
 height: 10px;
 border-radius: 50%;
 display: inline-block;
 box-shadow: 0 0 8px currentColor;
 animation: dot-pulse 2s ease-in-out infinite;
}

@keyframes dot-pulse {
 0%, 100% { opacity: 1; }
 50% { opacity: 0.6; }
}

.metric-label {
 font-size: 0.875rem;
 color: var(--do-text-secondary);
 font-weight: 500;
}

.metric-value {
 display: flex;
 align-items: baseline;
}

.metric-number {
 font-size: 2.5rem;
 font-weight: 800;
 color: var(--do-text-primary);
 letter-spacing: -0.02em;
}

.metric-loading {
 font-size: 2rem;
 color: var(--do-text-muted);
 animation: blink 1s steps(3) infinite;
}

@keyframes blink {
 0%, 100% { opacity: 1; }
 50% { opacity: 0.3; }
}

/* ===== FOOTER ===== */
.darkops-footer {
 text-align: center;
 padding: 24px;
 border-top: 1px solid rgba(139, 92, 246, 0.1);
 color: var(--do-text-muted);
 font-size: 0.8rem;
}

/* ===== RESPONSIVE ===== */
@media (max-width: 768px) {
 .darkops-header {
 padding: 40px 16px 24px;
 }

 .header-title {
 font-size: 2.25rem;
 }

 .header-subtitle {
 font-size: 1rem;
 }

 .cta-button {
 padding: 14px 24px;
 gap: 12px;
 }

 .cta-desc {
 display: none;
 }

 .cards-grid {
 grid-template-columns: 1fr;
 gap: 16px;
 }

 .metrics-grid {
 grid-template-columns: repeat(2, 1fr);
 gap: 12px;
 }

 .metric-number {
 font-size: 2rem;
 }

 .darkops-main {
 padding: 0 16px 40px;
 }
}

@media (max-width: 480px) {
 .metrics-grid {
 grid-template-columns: 1fr;
 }

 .header-title {
 font-size: 1.75rem;
 }

 .cta-button {
 width: 100%;
 justify-content: center;
 }
}
","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
}","import React from "react";
